UPDATE
    TBL_COMMON_FILE_S
SET
    file_save_nm = #{savedNm}
WHERE
    file_sq = #{fileSq}

UPDATE
    TBL_COMPANY_S c
    INNER JOIN (
    SELECT company_sq FROM TBL_COMPANY_S WHERE user_sq = #{userSq}
    UNION
    SELECT company_sq FROM TBL_COMPANY_MEMBER_R
    WHERE user_sq = #{userSq} AND company_member_status_cd = 401
    ) target ON c.company_sq = target.company_sq
    SET
        c.company_nm = #{companyNm}
